<?php $setups=$_SESSION['webhook_setups']??[]; if(isset($_SESSION['webhook_setup'])) $setups[]=$_SESSION['webhook_setup']; unset($_SESSION['webhook_setups'],$_SESSION['webhook_setup']); foreach($setups as $setup): ?><div class="notice"><div><strong>Configuration du webhook<?= isset($setup['repository'])?' · '.e($setup['repository']):'' ?> — à conserver maintenant</strong><p>URL : <code><?= e($setup['url']) ?></code></p><p>Secret : <code><?= e($setup['secret']) ?></code></p><small>Activez les événements push et pull request. Le secret sera masqué lors des prochaines visites.</small></div></div><?php endforeach; ?>
<div class="feature-banner development-banner"><span class="feature-orb"><?= icon('code') ?></span><div><span class="eyebrow">DU TICKET AU CODE</span><h2>Les idées et le code, reliés.</h2><p>Ajoutez la clé d’un ticket dans une branche ou une pull request.<br>Sillage rassemble le contexte au même endroit.</p></div><?php if($user['role']==='admin'): ?><button class="button primary" data-open="connection-dialog"><?= icon('plus') ?>Connecter un dépôt</button><?php endif; ?></div>
<div class="tabs development-tabs"><button class="selected" data-dev-tab="connections">Connexions <span><?= count($connections) ?></span></button><button data-dev-tab="pull_request">Pull requests</button><button data-dev-tab="commit">Commits</button><button data-dev-tab="repositories">Dépôts</button></div><section data-dev-panel="connections"><div class="connection-grid"><?php foreach(['github'=>['GitHub','GH','Du code à la collaboration.'],'bitbucket'=>['Bitbucket','BB','Vos dépôts, au plus près des projets.']] as $provider=>[$name,$mark,$desc]): $connected=array_filter($connections,fn($c)=>$c['provider']===$provider); ?><article class="panel connection-card"><div class="provider-mark"><?= e($mark) ?></div><h2><?= e($name) ?></h2><p><?= e($desc) ?></p><span class="pill <?= $connected?'success':'neutral' ?>"><?= $connected?count($connected).' dépôt(s) connecté(s)':'À connecter' ?></span><?php if($user['role']==='admin'): ?><button class="button subtle" data-open="<?= $connected?'provider-settings-'.e($provider):'connection-dialog' ?>" <?= !$connected?'data-connection-provider="'.e($provider).'"':'' ?>>Configurer <?= icon('arrow') ?></button><?php endif; ?></article><?php endforeach; ?></div><p class="help-text">La synchronisation manuelle examine jusqu’à 50 pull requests par dépôt ; les webhooks complètent les changements reçus ensuite. Les déploiements, mesures DORA, agents de code et scans de vulnérabilités nécessitent des intégrations supplémentaires et ne sont pas simulés.</p></section>
<?php foreach(['pull_request'=>'Pull requests','commit'=>'Commits'] as $kind=>$label): ?><section data-dev-panel="<?= e($kind) ?>" hidden><div class="panel"><h2><?= e($label) ?></h2><?php $filteredEvents=array_filter($events,fn($e)=>$e['kind']===$kind); foreach($filteredEvents as $event): ?><div class="dev-event"><span class="type-icon type-story"><?= icon('code') ?></span><div><a href="<?= e($event['external_url']) ?>" target="_blank" rel="noopener"><?= e($event['title']) ?></a><small><?= e($event['repository']) ?> · <?= e($event['occurred_at']) ?></small></div><span class="pill neutral"><?= e($event['state']) ?></span><?php if($event['ticket_id']): ?><a class="ticket-key" href="/tickets/<?= (int)$event['ticket_id'] ?>"><?= e($event['project_key'].'-'.$event['number']) ?></a><?php endif; ?></div><?php endforeach; if(!$filteredEvents): ?><div class="mini-empty"><?= icon('code') ?><p>Aucun événement reçu pour le moment.</p></div><?php endif; ?></div></section><?php endforeach; ?>
<section data-dev-panel="repositories" hidden><div class="panel"><h2>Vos dépôts</h2><?php foreach($connections as $c): ?><div class="repository-row"><span class="provider-mark small"><?= $c['provider']==='github'?'GH':'BB' ?></span><div><strong><?= e($c['repository']) ?></strong><small>Dernière synchronisation : <?= e($c['last_sync_at']??'jamais') ?></small></div><?php if($user['role']==='admin'): ?><form method="post" action="/connections/<?= (int)$c['id'] ?>/sync"><?= csrf() ?><button class="button subtle">Synchroniser</button></form><form method="post" action="/connections/<?= (int)$c['id'] ?>/delete"><?= csrf() ?><button class="text-button danger" data-confirm="Déconnecter ce dépôt et supprimer son historique local ?">Déconnecter</button></form><?php endif; ?></div><?php endforeach; if(!$connections): ?><p class="muted">Connectez votre premier dépôt pour retrouver son activité ici.</p><?php endif; ?></div></section>
<?php if($user['role']==='admin') require ROOT . '/app/Views/partials/connection-dialog.php'; ?>
